// SPDX-License-Identifier: MIT
pragma solidity 0.8.18;

import { HederaTokenService, IHederaTokenService } from "./lib/HederaTokenService.sol";
import { HederaResponseCodes } from "./lib/HederaResponseCodes.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title LDY HTS
 * @author Ledgity Team
 * @dev ERC20-compatible wrapper for LDY token that uses Hedera Token Service under the hood.
 * This contract implements the ERC20 interface but uses HTS functions for all operations.
 *
 * IMPORTANT NOTES:
 * - Token association must be done via Hedera SDK before an account can receive tokens
 * - Token allowance approval must be done via Hedera SDK before transferFrom can be called
 * - Initial supply is minted to the contract creator, who must have their account associated with the token
 *
 * @custom:security-contact security@ledgity.com
 */
contract LDYHTS is HederaTokenService, Ownable {
  // Token address once created
  address public tokenAddress;

  // Token metadata
  string public constant name = "Ledgity Token";
  string public constant symbol = "LDY";
  uint8 public constant decimals = 18;
  uint256 public constant totalSupply = 75_000_000 * 10 ** 18;

  // Mapping of account balances
  mapping(address => uint256) private _balances;

  // Mapping to track if an account has been associated with the token
  mapping(address => bool) private _associated;

  // Events
  event TokenCreated(address tokenAddress);
  event TokenAssociated(address account);
  event TokenDissociated(address account);

  // Custom errors
  error TokenNotCreated();
  error TokenAlreadyCreated();
  error TokenAssociationFailed(int responseCode);
  error TokenDissociationFailed(int responseCode);
  error TransferFailed(int responseCode);
  error MintFailed(int responseCode);
  error BurnFailed(int responseCode);
  error ApprovalFailed(int responseCode);

  /**
   * @dev Constructor that creates the HTS token and mints the initial supply to the contract creator.
   * The contract creator must have their account associated with the token before deployment.
   */
  constructor() {
    IHederaTokenService.TokenKey[]
      memory tokenKeys = new IHederaTokenService.TokenKey[](1);

    // tokenKey.push(IHederaTokenService
    //   .TokenKey({
    //     keyType: 1, // Admin key
    //     key: IHederaTokenService.KeyValue({
    //       inheritAccountKey: false,
    //       contractId: address(this)
    //     })
    //   }));

    // Create the HTS token
    IHederaTokenService.HederaToken memory tokenConfig = IHederaTokenService
      .HederaToken({
        name: name,
        symbol: symbol,
        treasury: address(this),
        tokenSupplyType: true,
        maxSupply: int64(uint64(totalSupply)),
        freezeDefault: false,
        memo: "Ledgity Token",
        expiry: IHederaTokenService.Expiry({
          autoRenewAccount: address(this),
          autoRenewPeriod: 90 * 24 * 60 * 60, // 90 days in seconds
          second: 0
        }),
        tokenKeys: tokenKeys
      });

    // Create the fungible token
    (int responseCode, address token) = createFungibleToken(
      tokenConfig,
      int64(uint64(totalSupply)),
      18
    );

    if (
      responseCode != HederaResponseCodes.SUCCESS ||
      tokenAddress == address(0)
    ) revert("Token creation failed");

    tokenAddress = token;

    emit TokenCreated(tokenAddress);
  }

  /**
   * @dev Transfers tokens from the contract to the owner after deployment.
   * The owner must have their account associated with the token before calling this function.
   */
  function transferInitialSupply() external onlyOwner {
    if (tokenAddress == address(0)) revert TokenNotCreated();

    int responseCode = transferToken(
      tokenAddress,
      address(this),
      owner(),
      int64(uint64(totalSupply))
    );

    if (responseCode != HederaResponseCodes.SUCCESS) {
      revert TransferFailed(responseCode);
    }
  }

  /**
   * @dev Returns the amount of tokens owned by `account`.
   */
  function balanceOf(
    address account
  ) external view returns (uint256) {
    return _balances[account];
  }
}

